{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case field")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("invalid case field type")
    if not nodes:
        raise ValueError("tree must contain a root")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required_symbols must contain strings")

    required_fields = {"id", "parent", "symbol", "depth", "removable", "utility"}
    by_id = {}
    source_order = []
    roots = []
    for node in nodes:
        if not isinstance(node, dict) or not required_fields.issubset(node):
            raise ValueError("invalid node")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or not isinstance(symbol, str):
            raise ValueError("node id and symbol must be strings")
        if node_id in by_id:
            raise ValueError("node ids must be unique")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("node parent must be a string or null")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("node depth must be a nonnegative integer")
        if not isinstance(removable, bool):
            raise ValueError("node removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("node utility must be finite")
        by_id[node_id] = node
        source_order.append(node_id)
        if parent is None:
            roots.append(node_id)

    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root_id = roots[0]
    if by_id[root_id]["depth"] != 0:
        raise ValueError("root depth must be zero")

    children = {node_id: [] for node_id in source_order}
    for node_id in source_order:
        node = by_id[node_id]
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id or parent == node_id:
            raise ValueError("invalid parent reference")
        if node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("inconsistent node depth")
        children[parent].append(node_id)

    present_symbols = {node["symbol"] for node in nodes}
    if any(symbol not in present_symbols for symbol in required_symbols):
        raise ValueError("required symbol is absent")

    retained = set(source_order)
    symbol_counts = {}
    for node in nodes:
        symbol = node["symbol"]
        symbol_counts[symbol] = symbol_counts.get(symbol, 0) + 1

    removed = []
    candidates = sorted(
        source_order,
        key=lambda node_id: (-by_id[node_id]["depth"], node_id),
    )
    required_set = set(required_symbols)
    for node_id in candidates:
        node = by_id[node_id]
        if node_id == root_id or not node["removable"]:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        symbol = node["symbol"]
        if symbol in required_set and symbol_counts[symbol] <= 1:
            continue
        retained.remove(node_id)
        symbol_counts[symbol] -= 1
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
